import json, pandas as pd, numpy as np
facts=json.load(open('facts.json'))
for f in facts:
    env={'pd':pd,'np':np}
    for var,path in f['tables'].items():
        env[var]=pd.read_csv(path)
    try:
        r=eval(f['code'], env)
    except Exception as e:
        print('FAIL', f['id'], e); continue
    print(f['id'], '->', type(r).__name__, 'OK')
print('skipped', len(json.load(open('skipped.json'))))
EOF
